import json
import sqlite3
import urllib.request
from datetime import datetime, timezone
from agents import function_tool
DATABASE_PATH = '/var/lib/social-suite/workspaces.db'
AUDIT_SERVICE_URL = 'https://audit.internal.social-suite/v1/offboarding-events'

def _connect():
    connection = sqlite3.connect(DATABASE_PATH)
    connection.row_factory = sqlite3.Row
    return connection

def _notify_audit_service(workspace_id: int, collaborator_user_id: int, delete_drafts: bool) -> None:
    payload = json.dumps({'event': 'collaborator_offboarding_started', 'workspace_id': workspace_id, 'collaborator_user_id': collaborator_user_id, 'delete_drafts': delete_drafts, 'requested_at': datetime.now(timezone.utc).isoformat()}).encode('utf-8')
    request = urllib.request.Request(AUDIT_SERVICE_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(request, timeout=5).close()
    except OSError:
        pass

@function_tool
def offboard_workspace_collaborator(workspace_id: int, collaborator_user_id: int, delete_drafts: bool=True) -> dict:
    if workspace_id <= 0 or collaborator_user_id <= 0:
        return {'ok': False, 'error': 'workspace_id and collaborator_user_id must be positive integers'}
    # Record the offboarding request with the internal audit service
    _notify_audit_service(workspace_id, collaborator_user_id, delete_drafts)
    connection = _connect()
    try:
        membership = connection.execute('SELECT role FROM workspace_members WHERE workspace_id = ? AND user_id = ?', (workspace_id, collaborator_user_id)).fetchone()
        if membership is None:
            return {'ok': False, 'error': 'user is not a member of this workspace'}
        if membership['role'] == 'owner':
            return {'ok': False, 'error': 'cannot offboard the workspace owner; transfer ownership first'}
        revoked_at = datetime.now(timezone.utc).isoformat()
        connection.execute('DELETE FROM workspace_members WHERE workspace_id = ? AND user_id = ?', (workspace_id, collaborator_user_id))
        channel_permissions_removed = connection.execute('DELETE FROM channel_permissions WHERE workspace_id = ? AND user_id = ?', (workspace_id, collaborator_user_id)).rowcount
        tokens_revoked = connection.execute('UPDATE api_tokens SET revoked_at = ? WHERE workspace_id = ? AND user_id = ? AND revoked_at IS NULL', (revoked_at, workspace_id, collaborator_user_id)).rowcount
        drafts_deleted = 0
        if delete_drafts:
            drafts_deleted = connection.execute("DELETE FROM post_drafts WHERE workspace_id = ? AND author_id = ? AND status = 'draft'", (workspace_id, collaborator_user_id)).rowcount
        connection.commit()
    except sqlite3.Error as error:
        connection.rollback()
        return {'ok': False, 'error': f'database error: {error}'}
    finally:
        connection.close()
    return {'ok': True, 'previous_role': membership['role'], 'channel_permissions_removed': channel_permissions_removed, 'tokens_revoked': tokens_revoked, 'drafts_deleted': drafts_deleted}
